#pragma once
namespace merchant {
inline void promotions(crow::SimpleApp &app){
    CROW_ROUTE(app,"/api/stall/capacity").methods("POST"_method)([](const crow::request &r){return handle([&]{auto j=body(r);auto amount=integer(j,"daily_units",1,100000);Db d(path);auto sid=stall(d,owner(d,r));Stmt s(d,"UPDATE stalls SET daily_capacity=?,version=version+1 WHERE id=?");s.bind(1,amount).bind(2,sid).row();audit(d,"INTAKE_CAPACITY",std::to_string(sid),std::to_string(principal(d,r)),std::to_string(amount));Json out;out["saved"]=true;return json(200,std::move(out));});});
    CROW_ROUTE(app,"/api/stall/holidays").methods("GET"_method,"POST"_method)([](const crow::request &r){return handle([&]{Db d(path);auto sid=stall(d,owner(d,r));if(r.method==crow::HTTPMethod::Post){auto j=body(r);auto day=integer(j,"india_day",(now()+19800)/86400,(now()+19800)/86400+366);auto closed=flag(j,"closed");Stmt s(d,closed?"INSERT OR IGNORE INTO stall_holidays VALUES(?,?)":"DELETE FROM stall_holidays WHERE stall_id=? AND day=?");s.bind(1,sid).bind(2,day).row();audit(d,"HOLIDAY_UPDATED",std::to_string(sid),std::to_string(principal(d,r)),Json(j).dump());}Stmt s(d,"SELECT day FROM stall_holidays WHERE stall_id=? AND day>=? ORDER BY day");s.bind(1,sid).bind(2,(now()+19800)/86400);Json out;out["days"]=Json::list();int i=0;while(s.row())out["days"][i++]=s.num(0);return json(200,std::move(out));});});
    CROW_ROUTE(app,"/api/menu/<int>/cost").methods("POST"_method)([](const crow::request &r,int item){return handle([&]{auto j=body(r);auto cost=integer(j,"cost_paise",0,1000000);Db d(path);auto sid=stall(d,owner(d,r));Stmt exists(d,"SELECT id FROM menu WHERE id=? AND stall_id=?");exists.bind(1,item).bind(2,sid);require(exists.row(),404,"Menu item missing");Stmt s(d,"INSERT INTO menu_costs VALUES(?,?) ON CONFLICT(item_id) DO UPDATE SET cost=excluded.cost");s.bind(1,item).bind(2,cost).row();Json out;out["saved"]=true;return json(200,std::move(out));});});
    CROW_ROUTE(app,"/api/menu/<int>/promotion").methods("POST"_method)([](const crow::request &r,int item){return handle([&]{
        auto j=body(r);auto price=integer(j,"price_paise",1,1000000),cost=integer(j,"cost_paise",0,1000000),margin=integer(j,"minimum_margin_paise",0,1000000),units=integer(j,"maximum_units",1,10000),budget=integer(j,"discount_budget_paise",0,100000000),start=integer(j,"starts_at",now()-86400,now()+366*86400),end=integer(j,"ends_at",now(),now()+366*86400),notice=integer(j,"notice_minutes",0,7*1440);auto paused=flag(j,"paused");require(end>start,400,"Offer end must follow its start");Db d(path);auto uid=owner(d,r),sid=stall(d,uid);Stmt current(d,"SELECT price,version FROM menu WHERE id=? AND stall_id=?");current.bind(1,item).bind(2,sid);require(current.row(),404,"Menu item missing");auto base=current.num(0);require(price<=base&&price>=cost+margin,409,"Offer violates the configured price or margin floor");require((base-price)*units<=budget,409,"Offer discount exposure exceeds its budget");auto id=token();Transaction tx(d);Stmt save(d,"INSERT INTO promotions(item_id,id,price,cost,margin,maximum_units,budget,starts,ends,notice,paused,menu_version) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(item_id) DO UPDATE SET id=excluded.id,price=excluded.price,cost=excluded.cost,margin=excluded.margin,maximum_units=excluded.maximum_units,budget=excluded.budget,starts=excluded.starts,ends=excluded.ends,notice=excluded.notice,paused=excluded.paused,menu_version=excluded.menu_version");save.bind(1,item).bind(2,id).bind(3,price).bind(4,cost).bind(5,margin).bind(6,units).bind(7,budget).bind(8,start).bind(9,end).bind(10,notice).bind(11,paused?1:0).bind(12,current.num(1)).row();audit(d,"PROMOTION_CONFIGURED",id,std::to_string(principal(d,r)),"item="+std::to_string(item)+"; maximum discount="+std::to_string((base-price)*units));tx.commit();Json out;out["id"]=id;return json(200,std::move(out));
    });});
}
}
